tool_input.content:
const fs = require("fs");
const vm = require("vm");
const html = fs.readFileSync(process.argv[2], "utf8");
let code = html.match(/<script>([\s\S]*)<\/script>/)[1];
code = code.slice(0, code.indexOf("/* ================= UI"));
const ctx = { document: { getElementById: () => ({ value: "1337" }) }, console, Math, JSON };
vm.createContext(ctx);
vm.runInContext(code, ctx);
console.log(ctx.runTests());
const b1 = ctx.runBenchmark(), b2 = ctx.runBenchmark();
console.log(b1);
console.log("benchmark deterministic:", b1 === b2);
